G=load()

def transform(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    # find crosses: 3x3 with all 3s and center 2
    crosses=[]
    for r in range(H-2):
        for c in range(W-2):
            if all(g[r+i][c+j]==3 for i in range(3) for j in range(3)) and g[r+1][c+1]==2:
                crosses.append((r+1,c+1))
    # find lines: columns that are mostly 2 (vertical) or rows mostly 2
    vlines=[c for c in range(W) if sum(g[r][c]==2 for r in range(H))>=H-3]
    hlines=[r for r in range(H) if sum(g[r][c]==2 for c in range(W))>=W-3]
    for (r,c) in crosses:
        if len(vlines)>=2 and c in vlines:
            others=[x for x in vlines if x!=c]
            tgt=min(others,key=lambda x:abs(x-c))
            pr,pc=r,tgt
            bar=[(pr,j) for j in range(W)]
        elif len(hlines)>=2 and r in hlines:
            others=[x for x in hlines if x!=r]
            tgt=min(others,key=lambda x:abs(x-r))
            pr,pc=tgt,c
            bar=[(i,pc) for i in range(H)]
        else:
            continue
        # 3x3 block, center unchanged
        for i in range(pr-1,pr+2):
            for j in range(pc-1,pc+2):
                if (i,j)!=(pr,pc) and 0<=i<H and 0<=j<W:
                    out[i][j]=1
        # bar: overwrite only 0s
        for (i,j) in bar:
            if out[i][j]==0:
                out[i][j]=1
    return out

